const e={title_add:"Eigenes CLI hinzufügen",title_edit:"Dieses CLI bearbeiten",description:"Jedes interaktive Terminal-CLI kann hier in einem Pane laufen. Name und Startbefehl genügen — danach erscheint es überall dort, wo auch die mitgelieferten stehen.",close:"Schließen",cancel:"Abbrechen",save:"Speichern",save_add:"CLI hinzufügen",saving:"Wird gespeichert…",name:"Name",name_placeholder:"z. B. Aider",name_hint:"So steht es in den Auswahllisten — und so sprichst du es an.",command:"Befehl",command_placeholder:"aider",command_hint:"Genau das, was du im Terminal eintippen würdest, um es zu starten.",command_shell_hint:"Das läuft über eine Shell, weil der Befehl aus mehr als einem Programm besteht. Der Pane schließt sich, wenn die ganze Zeile durch ist.",description_label:"Beschreibung",optional:"Optional",description_placeholder:"Eine Zeile, was dieses CLI ist.",at_reference:"Abgelegte Dateien als @Pfad schreiben",at_reference_hint:"Die meisten modernen Coding-CLIs lesen @Pfad als zu öffnende Datei. Ausgeschaltet werden Pfade in Anführungszeichen eingefügt.",threads_title:"In Threads ausführen (optional)",headless_command:"Headless-Befehl",headless_command_hint:"Lässt diese CLI auch als Anbieter in Agentic-IDE-Threads erscheinen. Setze {prompt} dorthin, wo die Nachricht hin soll; ohne {prompt} wird die Nachricht über stdin gesendet. Die Antwort ist, was der Befehl ausgibt.",headless_resume:"Fortsetzungsbefehl",headless_resume_hint:"Wird für Folgenachrichten verwendet. {session} wird durch die Konversations-ID ersetzt. Leer lassen, um jede Runde neu zu beginnen.",pick_logo:"Logo auswählen",remove_logo:"Logo entfernen",remove_logo_short:"Entfernen",logo_label:"Logo"},n={custom_cli:e};export{e as custom_cli,n as default};
